package com.aifacemate.face.voice.asr.client
import com.aifacemate.face.network.NetworkClient
import com.aifacemate.face.voice.asr.internal.base64Encode
import com.aifacemate.face.voice.asr.catalog.defaultAsrProviders
import com.aifacemate.face.voice.asr.model.AsrRequest
import com.aifacemate.face.voice.asr.model.AsrResult
class AsrClient(private val network: NetworkClient) { suspend fun transcribe(request: AsrRequest): AsrResult { if(request.apiKey.isBlank())return AsrResult.Failure("请先填写 ASR API Key");if(request.audio.isEmpty())return AsrResult.Failure("录音内容为空");val provider=defaultAsrProviders.firstOrNull{it.id==request.providerId}?:return AsrResult.Failure("不支持的 ASR 供应商：${request.providerId}");val mime=if(request.mimeType=="audio/mpeg"||request.mimeType=="audio/mp3")"audio/mpeg" else "audio/wav";val body="{\"model\":\"${request.model}\",\"messages\":[{\"role\":\"user\",\"content\":[{\"type\":\"input_audio\",\"input_audio\":{\"data\":\"data:$mime;base64,${request.audio.base64Encode()}\"}}]}],\"asr_options\":{\"language\":\"${request.language?:"auto"}\"},\"stream\":false}";val endpoint="${request.baseUrl?:provider.baseUrl}/chat/completions";val response=network.postJson(endpoint,mapOf("api-key" to request.apiKey.trim()),body);if(response.statusCode !in 200..299)return AsrResult.Failure("ASR 请求失败（HTTP ${response.statusCode}）",response.statusCode);val text=Regex("\\\"content\\\"\\s*:\\s*\\\"((?:\\\\.|[^\"])*)\\\"").find(response.text)?.groupValues?.get(1)?.replace("\\n","\n")?.replace("\\\"","\"");return if(text.isNullOrBlank())AsrResult.Failure("ASR 返回格式无法解析",response.statusCode)else AsrResult.Success(text)} }
